import type { ToolUseBlock } from '@anthropic-ai/sdk/resources/index.mjs'
import last from 'lodash-es/last.js'
import {
  getSessionId,
  isSessionPersistenceDisabled,
} from '@thyrox/app-host/bootstrap/state.js'
import type { SDKMessage } from '@thyrox/headless-sdk/agentSdkTypes.js'
import type { CanUseToolFn } from './hooks/useCanUseTool.js'
import { runTools } from '@thyrox/tool-registry/services/toolOrchestration.js'
import { findToolByName, type Tool, type Tools } from '@thyrox/tool-registry/Tool.js'
import { BASH_TOOL_NAME } from '@thyrox/tool-registry/tools/BashTool/toolName.js'
import { FILE_EDIT_TOOL_NAME } from '@thyrox/tool-registry/tools/FileEditTool/constants.js'
import type { Input as FileReadInput } from '@thyrox/tool-registry/tools/FileReadTool/FileReadTool.js'
import {
  FILE_READ_TOOL_NAME,
  FILE_UNCHANGED_STUB,
} from '@thyrox/tool-registry/tools/FileReadTool/prompt.js'
import { FILE_WRITE_TOOL_NAME } from '@thyrox/tool-registry/tools/FileWriteTool/prompt.js'
import type { Message } from '@thyrox/agent/messageShapes'
import type { OrphanedPermission } from './textInputTypes.js'
import { logForDebugging } from '@thyrox/local-observability/debug.js'
import { isEnvTruthy } from '@thyrox/config/env/utils'
import { isFsInaccessible } from '@thyrox/local-observability/errorHelpers.js'
import { getFileModificationTime, stripLineNumberPrefix } from '@thyrox/storage/file.js'
import { readFileSyncWithMetadata } from '@thyrox/storage/fileRead.js'
import {
  createFileStateCacheWithSizeLimit,
  type FileStateCache,
} from '@thyrox/tool-registry/fileStateCache'
import { isNotEmptyMessage, normalizeMessages } from '@thyrox/agent/messages.js'
import { expandPath } from '@thyrox/storage/path.js'
import type {
  inputSchema as permissionToolInputSchema,
  outputSchema as permissionToolOutputSchema,
} from '@thyrox/permission/PermissionPromptToolResultSchema'
import type { ProcessUserInputContext } from './processUserInput/processUserInput.js'
import { recordTranscript } from '@thyrox/storage/sessionStorage.js'

export type PermissionPromptTool = Tool<
  ReturnType<typeof permissionToolInputSchema>,
  ReturnType<typeof permissionToolOutputSchema>
>

// Small cache size for ask operations which typically access few files
// during permission prompts or limited tool operations
const ASK_READ_FILE_STATE_CACHE_SIZE = 10

/** Transcript JSON may deserialize Write tool `content` as a nested object — LRU needs strings. */
function coerceToolContentToString(value: unknown): string {
  if (typeof value === 'string') return value
  if (value === null || value === undefined) return ''
  if (typeof value === 'object') return JSON.stringify(value)
  return String(value)
}

/**
 * Checks if the result should be considered successful based on the last message.
 * Returns true if:
 * - Last message is assistant with text/thinking content
 * - Last message is user with only tool_result blocks
 * - Last message is the user prompt but the API completed with end_turn
 *   (model chose to emit no content blocks)
 */
export function isResultSuccessful(
  message: Message | undefined,
  stopReason: string | null = null,
): message is Message {
  if (!message) return false

  if (message.type === 'assistant') {
    const content = message.message.content
    const lastContent = Array.isArray(content) ? last(content) : undefined
    return (
      lastContent?.type === 'text' ||
      lastContent?.type === 'thinking' ||
      lastContent?.type === 'redacted_thinking'
    )
  }

  if (message.type === 'user') {
    // Check if all content blocks are tool_result type
    const content = message.message.content
    if (
      Array.isArray(content) &&
      content.length > 0 &&
      content.every(block => 'type' in block && block.type === 'tool_result')
    ) {
      return true
    }
  }

  // Carve-out: API completed (message_delta set stop_reason) but yielded
  // no assistant content — last(messages) is still this turn's prompt.
  // claude.ts:2026 recognizes end_turn-with-zero-content-blocks as
  // legitimate and passes through without throwing. Observed on
  // task_notification drain turns: model returns stop_reason=end_turn,
  // outputTokens=4, textContentLength=0 — it saw the subagent result
  // and decided nothing needed saying. Without this, QueryEngine emits
  // error_during_execution with errors[] = the entire process's
  // accumulated logError() buffer. Covers both string-content and
  // text-block-content user prompts, and any other non-passing shape.
  return stopReason === 'end_turn'
}

// Track last sent time for tool progress messages per tool use ID
// Keep only the last 100 entries to prevent unbounded growth
const MAX_TOOL_PROGRESS_TRACKING_ENTRIES = 100
const TOOL_PROGRESS_THROTTLE_MS = 30000
const toolProgressLastSentTime = new Map<string, number>()

export function* normalizeMessage(message: Message): Generator<SDKMessage> {
  switch (message.type) {
    case 'assistant':
      for (const _ of normalizeMessages([message])) {
        // Skip empty messages (e.g., "(no content)") that shouldn't be output to SDK
        if (!isNotEmptyMessage(_)) {
          continue
        }
        yield {
          type: 'assistant',
          message: _.message,
          parent_tool_use_id: null,
          session_id: getSessionId(),
          uuid: _.uuid,
          error: _.error,
        }
      }
      return
    case 'progress': {
      const progressData = message.data as { type: string; message: Message; elapsedTimeSeconds: number; taskId: string }
      if (
        progressData.type === 'agent_progress' ||
        progressData.type === 'skill_progress'
      ) {
        for (const _ of normalizeMessages([progressData.message])) {
          switch (_.type) {
            case 'assistant':
              // Skip empty messages (e.g., "(no content)") that shouldn't be output to SDK
              if (!isNotEmptyMessage(_)) {
                break
              }
              yield {
                type: 'assistant',
                message: _.message,
                parent_tool_use_id: message.parentToolUseID as string,
                session_id: getSessionId(),
                uuid: _.uuid,
                error: _.error,
              }
              break
            case 'user':
              yield {
                type: 'user',
                message: _.message,
                parent_tool_use_id: message.parentToolUseID as string,
                session_id: getSessionId(),
                uuid: _.uuid,
                timestamp: _.timestamp as string | undefined,
                isSynthetic: _.isMeta || _.isVisibleInTranscriptOnly,
                tool_use_result: _.mcpMeta
                  ? { content: _.toolUseResult, ...(_.mcpMeta as Record<string, unknown>) }
                  : _.toolUseResult,
              }
              break
          }
        }
      } else if (
        progressData.type === 'bash_progress' ||
        progressData.type === 'powershell_progress'
      ) {
        // Filter bash progress to send only one per minute
        // Only emit for Claude Code Remote for now
        if (
          !isEnvTruthy(process.env.CLAUDE_CODE_REMOTE) &&
          !process.env.CLAUDE_CODE_CONTAINER_ID
        ) {
          break
        }

        // Use parentToolUseID as the key since toolUseID changes for each progress message
        const trackingKey = message.parentToolUseID as string
        const now = Date.now()
        const lastSent = toolProgressLastSentTime.get(trackingKey) || 0
        const timeSinceLastSent = now - lastSent

        // Send if at least 30 seconds have passed since last update
        if (timeSinceLastSent >= TOOL_PROGRESS_THROTTLE_MS) {
          // Remove oldest entry if we're at capacity (LRU eviction)
          if (
            toolProgressLastSentTime.size >= MAX_TOOL_PROGRESS_TRACKING_ENTRIES
          ) {
            const firstKey = toolProgressLastSentTime.keys().next().value
            if (firstKey !== undefined) {
              toolProgressLastSentTime.delete(firstKey)
            }
          }

          toolProgressLastSentTime.set(trackingKey, now)
          yield {
            type: 'tool_progress',
            tool_use_id: message.toolUseID as string,
            tool_name:
              progressData.type === 'bash_progress' ? 'Bash' : 'PowerShell',
            parent_tool_use_id: message.parentToolUseID as string,
            elapsed_time_seconds: progressData.elapsedTimeSeconds,
            task_id: progressData.taskId,
            session_id: getSessionId(),
            uuid: message.uuid,
          }
        }
      }
      break
    }
    case 'user':
      for (const _ of normalizeMessages([message])) {
        yield {
          type: 'user',
          message: _.message,
          parent_tool_use_id: null,
          session_id: getSessionId(),
          uuid: _.uuid,
          timestamp: _.timestamp as string | undefined,
          isSynthetic: _.isMeta || _.isVisibleInTranscriptOnly,
          tool_use_result: _.mcpMeta
            ? { content: _.toolUseResult, ...(_.mcpMeta as Record<string, unknown>) }
            : _.toolUseResult,
        }
      }
      return
    default:
    // yield nothing
  }
}

export async function* handleOrphanedPermission(
  orphanedPermission: OrphanedPermission,
  tools: Tools,
  mutableMessages: Message[],
  processUserInputContext: ProcessUserInputContext,
): AsyncGenerator<SDKMessage, void, unknown> {
  const persistSession = !isSessionPersistenceDisabled()
  const { permissionResult, assistantMessage } = orphanedPermission
  const toolUseID = (permissionResult as { toolUseID?: string }).toolUseID

  if (!toolUseID) {
    return
  }

  const content = assistantMessage.message.content
  let toolUseBlock: ToolUseBlock | undefined
  if (Array.isArray(content)) {
    for (const block of content) {
      if (block.type === 'tool_use' && block.id === toolUseID) {
        toolUseBlock = block as ToolUseBlock
        break
      }
    }
  }

  if (!toolUseBlock) {
    return
  }

  const toolName = toolUseBlock.name
  const toolInput = toolUseBlock.input

  const toolDefinition = findToolByName(tools, toolName)
  if (!toolDefinition) {
    return
  }

  // Create ToolUseBlock with the updated input if permission was allowed
  let finalInput = toolInput
  if (permissionResult.behavior === 'allow') {
    const allowResult = permissionResult as { behavior: 'allow'; updatedInput?: unknown }
    if (allowResult.updatedInput !== undefined) {
      finalInput = allowResult.updatedInput
    } else {
      logForDebugging(
        `Orphaned permission for ${toolName}: updatedInput is undefined, falling back to original tool input`,
        { level: 'warn' },
      )
    }
  }
  const finalToolUseBlock: ToolUseBlock = {
    ...toolUseBlock,
    input: finalInput,
  }

  const canUseTool: CanUseToolFn = (async () => {
    if (permissionResult.behavior === 'allow') {
      return {
        behavior: 'allow' as const,
        updatedInput: (permissionResult as { updatedInput?: Record<string, unknown> }).updatedInput,
        decisionReason: {
          type: 'mode' as const,
          mode: 'default' as const,
        },
      }
    }
    return {
      behavior: 'deny' as const,
      message: (permissionResult as { message?: string }).message,
      decisionReason: {
        type: 'mode' as const,
        mode: 'default' as const,
      },
    }
  }) as CanUseToolFn

  // Add the assistant message with tool_use to messages BEFORE executing
  // so the conversation history is complete (tool_use -> tool_result).
  //
  // On CCR resume, mutableMessages is seeded from the transcript and may already
  // contain this tool_use. Pushing again would make normalizeMessagesForAPI merge
  // same-ID assistants (concatenating content) and produce a duplicate tool_use
  // ID, which the API rejects with "tool_use ids must be unique".
  //
  // Check for the specific tool_use_id rather than message.id: streaming yields
  // each content block as a separate AssistantMessage sharing one message.id, so
  // a [text, tool_use] response lands as two entries. filterUnresolvedToolUses may
  // strip the tool_use entry but keep the text one; an id-based check would then
  // wrongly skip the push while runTools below still executes, orphaning the result.
  const alreadyPresent = mutableMessages.some(
    m =>
      m.type === 'assistant' &&
      Array.isArray(m.message.content) &&
      m.message.content.some(
        b => b.type === 'tool_use' && 'id' in b && b.id === toolUseID,
      ),
  )
  if (!alreadyPresent) {
    mutableMessages.push(assistantMessage)
    if (persistSession) {
      await recordTranscript(mutableMessages)
    }
  }

  const sdkAssistantMessage: SDKMessage = {
    ...assistantMessage,
    session_id: getSessionId(),
    parent_tool_use_id: null,
  } as SDKMessage
  yield sdkAssistantMessage

  // Execute the tool - errors are handled internally by runToolUse
  for await (const update of runTools(
    [finalToolUseBlock],
    [assistantMessage],
    canUseTool,
    processUserInputContext,
  )) {
    if (update.message) {
      mutableMessages.push(update.message)
      if (persistSession) {
        await recordTranscript(mutableMessages)
      }

      const sdkMessage: SDKMessage = {
        ...update.message,
        session_id: getSessionId(),
        parent_tool_use_id: null,
      } as SDKMessage

      yield sdkMessage
    }
  }
}

// Create a function to extract read files from messages
export function extractReadFilesFromMessages(
  messages: Message[],
  cwd: string,
  maxSize: number = ASK_READ_FILE_STATE_CACHE_SIZE,
): FileStateCache {
  const cache = createFileStateCacheWithSizeLimit(maxSize)

  // First pass: find all FileReadTool/FileWriteTool/FileEditTool uses in assistant messages
  const fileReadToolUseIds = new Map<string, string>() // toolUseId -> filePath
  const fileWriteToolUseIds = new Map<
    string,
    { filePath: string; content: string }
  >() // toolUseId -> { filePath, content }
  const fileEditToolUseIds = new Map<string, string>() // toolUseId -> filePath

  for (const message of messages) {
    if (
      message.type === 'assistant' &&
      Array.isArray(message.message.content)
    ) {
      for (const content of message.message.content) {
        if (
          content.type === 'tool_use' &&
          content.name === FILE_READ_TOOL_NAME
        ) {
          // Extract file_path from the tool use input
          const input = content.input as FileReadInput | undefined
          // Ranged reads are not added to the cache.
          if (
            input?.file_path &&
            input?.offset === undefined &&
            input?.limit === undefined
          ) {
            // Normalize to absolute path for consistent cache lookups
            const absolutePath = expandPath(input.file_path, cwd)
            fileReadToolUseIds.set(content.id, absolutePath)
          }
        } else if (
          content.type === 'tool_use' &&
          content.name === FILE_WRITE_TOOL_NAME
        ) {
          // Extract file_path and content from the Write tool use input
          const input = content.input as
            | { file_path?: string; content?: unknown }
            | undefined
          if (
            input?.file_path &&
            input.content !== undefined &&
            input.content !== null
          ) {
            // Normalize to absolute path for consistent cache lookups
            const absolutePath = expandPath(input.file_path, cwd)
            fileWriteToolUseIds.set(content.id, {
              filePath: absolutePath,
              content: coerceToolContentToString(input.content),
            })
          }
        } else if (
          content.type === 'tool_use' &&
          content.name === FILE_EDIT_TOOL_NAME
        ) {
          // Edit's input has old_string/new_string, not the resulting content.
          // Track the path so the second pass can read current disk state.
          const input = content.input as { file_path?: string } | undefined
          if (input?.file_path) {
            const absolutePath = expandPath(input.file_path, cwd)
            fileEditToolUseIds.set(content.id, absolutePath)
          }
        }
      }
    }
  }

  // Second pass: find corresponding tool results and extract content
  for (const message of messages) {
    if (message.type === 'user' && Array.isArray(message.message.content)) {
      for (const content of message.message.content) {
        if (content.type === 'tool_result' && content.tool_use_id) {
          // Handle Read tool results
          const readFilePath = fileReadToolUseIds.get(content.tool_use_id)
          if (
            readFilePath &&
            typeof content.content === 'string' &&
            // Dedup stubs contain no file content — the earlier real Read
            // already cached it. Chronological last-wins would otherwise
            // overwrite the real entry with stub text.
            !content.content.startsWith(FILE_UNCHANGED_STUB)
          ) {
            // Remove system-reminder blocks from the content
            const processedContent = content.content.replace(
              /<system-reminder>[\s\S]*?<\/system-reminder>/g,
              '',
            )

            // Extract the actual file content from the tool result
            // Tool results for text files contain line numbers, we need to strip those
            const fileContent = processedContent
              .split('\n')
              .map(stripLineNumberPrefix)
              .join('\n')
              .trim()

            // Cache the file content with the message timestamp
            if (message.timestamp) {
              const timestamp = new Date(message.timestamp as string | number).getTime()
              cache.set(readFilePath, {
                content: fileContent,
                timestamp,
                offset: undefined,
                limit: undefined,
              })
            }
          }

          // Handle Write tool results - use content from the tool input
          const writeToolData = fileWriteToolUseIds.get(content.tool_use_id)
          if (writeToolData && message.timestamp) {
            const timestamp = new Date(message.timestamp as string | number).getTime()
            cache.set(writeToolData.filePath, {
              content: writeToolData.content,
              timestamp,
              offset: undefined,
              limit: undefined,
            })
          }

          // Handle Edit tool results — post-edit content isn't in the
          // tool_use input (only old_string/new_string) nor fully in the
          // result (only a snippet). Read from disk now, using actual mtime
          // so getChangedFiles's mtime check passes on the next turn.
          //
          // Callers seed the cache once at process start (print.ts --resume,
          // Cowork cold-restart per turn), so disk content at extraction time
          // IS the post-edit state. No dedup: processing every Edit preserves
          // last-wins semantics when Read/Write interleave (Edit→Read→Edit).
          const editFilePath = fileEditToolUseIds.get(content.tool_use_id)
          if (editFilePath && content.is_error !== true) {
            try {
              const { content: diskContent } =
                readFileSyncWithMetadata(editFilePath)
              cache.set(editFilePath, {
                content: diskContent,
                timestamp: getFileModificationTime(editFilePath),
                offset: undefined,
                limit: undefined,
              })
            } catch (e: unknown) {
              if (!isFsInaccessible(e)) {
                throw e
              }
              // File deleted or inaccessible since the Edit — skip
            }
          }
        }
      }
    }
  }

  return cache
}

/**
 * Extract the top-level CLI tools used in BashTool calls from message history.
 * Returns a deduplicated set of command names (e.g. 'vercel', 'aws', 'git').
 */
export function extractBashToolsFromMessages(messages: Message[]): Set<string> {
  const tools = new Set<string>()
  for (const message of messages) {
    if (
      message.type === 'assistant' &&
      Array.isArray(message.message.content)
    ) {
      for (const content of message.message.content) {
        if (content.type === 'tool_use' && content.name === BASH_TOOL_NAME) {
          const { input } = content
          if (
            typeof input !== 'object' ||
            input === null ||
            !('command' in input)
          )
            continue
          const cmd = extractCliName(
            typeof input.command === 'string' ? input.command : undefined,
          )
          if (cmd) {
            tools.add(cmd)
          }
        }
      }
    }
  }
  return tools
}

const STRIPPED_COMMANDS = new Set(['sudo'])

/**
 * Extract the actual CLI name from a bash command string, skipping
 * env var assignments (e.g. `FOO=bar vercel` → `vercel`) and prefixes
 * in STRIPPED_COMMANDS.
 */
function extractCliName(command: string | undefined): string | undefined {
  if (!command) return undefined
  const tokens = command.trim().split(/\s+/)
  for (const token of tokens) {
    if (/^[A-Za-z_]\w*=/.test(token)) continue
    if (STRIPPED_COMMANDS.has(token)) continue
    return token
  }
  return undefined
}

  }
}

/**
 * Defensive validation: ensure tool_use/tool_result pairing is correct.
 *
 * Handles both directions:
 * - Forward: inserts synthetic error tool_result blocks for tool_use blocks missing results
 * - Reverse: strips orphaned tool_result blocks referencing non-existent tool_use blocks
 *
 * Logs when this activates to help identify the root cause.
 *
 * Strict mode: when getStrictToolResultPairing() is true (HFI opts in at
 * startup), any mismatch throws instead of repairing. For training-data
 * collection, a model response conditioned on synthetic placeholders is
 * tainted — fail the trajectory rather than waste labeler time on a turn
 * that will be rejected at submission anyway.
 */


// ===========================================================================
// TRAMO 2 de TASK-THYROX-0212 — los dos simbolos que desbloquean la suite
// ===========================================================================
// El tramo NO se eligio por tamano: se DERIVO de los dos rojos que el
// subconjunto publicaba. Con `proper-lockfile` materializado, el error real
// salio a la luz y contradijo la atribucion del tramo 1:
//
//   message-pipeline.test.ts -> Export named 'normalizeMessages' not found
//   messages.test.ts         -> Export named 'prepareUserContent' not found
//
// Los dos rojos eran del SUJETO -el porte incompleto-, no premisa rancia.
// El `Cannot find package 'proper-lockfile'` los enmascaraba: el grafo de
// modulos moria antes de llegar a preguntar por el export.
//
// El cierre transitivo decide el corte, medido sobre la fuente:
//
//   normalizeMessages        cierre= 3   falta 1    ~84 lineas
//   prepareUserContent       cierre= 1   falta 1    ~19 lineas
//   normalizeMessagesForAPI  cierre=56   faltan 54  ~2766 lineas
//
// Los dos primeros entran aqui y cierran `message-pipeline.test.ts` entero
// -su unico ausente era `normalizeMessages`-. El hub queda para el tramo 3;
// `messages.test.ts` no puede cerrar antes, porque lo importa.
export function prepareUserContent({
  inputString,
  precedingInputBlocks,
}: {
  inputString: string
  precedingInputBlocks: ContentBlockParam[]
}): string | ContentBlockParam[] {
  if (precedingInputBlocks.length === 0) {
    return inputString
  }

  return [
    ...precedingInputBlocks,
    {
      text: inputString,
      type: 'text',
    },
  ]
}

export function normalizeMessages(messages: Message[]): NormalizedMessage[] {
  // isNewChain tracks whether we need to generate new UUIDs for messages when normalizing.
  // When a message has multiple content blocks, we split it into multiple messages,
  // each with a single content block. When this happens, we need to generate new UUIDs
  // for all subsequent messages to maintain proper ordering and prevent duplicate UUIDs.
  // This flag is set to true once we encounter a message with multiple content blocks,
  // and remains true for all subsequent messages in the normalization process.
  let isNewChain = false
  // Cada rama emite un bloque por mensaje: el contenido sale como arreglo por
  // construcción, que es la forma que `NormalizedMessage` declara.
  return messages.flatMap((message): NormalizedMessage[] => {
    switch (message.type) {
      case 'assistant': {
        // El `switch` NO estrecha: `Message.type` esta declarado `MessageType`
        // y no como literal discriminante, asi que TypeScript no deduce el
        // subtipo por rama. La rama SI lo garantiza, asi que se declara con un
        // cast en vez de sembrar `?.` en cada uno de los nueve accesos.
        const am = message as AssistantMessage
        // `content` sigue opcional dentro de `message` —la fuente lo lee sin
        // guarda bajo `strict: false`—, y el arreglo se estrecha a `ContentItem[]`
        // para que `.map` resuelva: una union `A[] | B[]` no ofrece una firma
        // de `map` compatible, y `ContentItem` es el elemento que
        // `messageShapes.ts` exporta para exactamente esto.
        const assistantContent = (Array.isArray(am.message.content)
          ? am.message.content
          : []) as ContentItem[]
        isNewChain = isNewChain || assistantContent.length > 1
        return assistantContent.map((_, index) => {
          const uuid = isNewChain
            ? deriveUUID(am.uuid, index)
            : am.uuid
          return {
            type: 'assistant' as const,
            timestamp: am.timestamp,
            message: {
              ...am.message,
              content: [_],

              context_management: am.message.context_management ?? null,
            },
            isMeta: am.isMeta,
            isVirtual: am.isVirtual,
            requestId: am.requestId,
            uuid,
            error: am.error,
            isApiErrorMessage: am.isApiErrorMessage,
            advisorModel: am.advisorModel,
          } as NormalizedAssistantMessage
        })
      }
      case 'attachment':
        return [message] as NormalizedMessage[]
      case 'progress':
        return [message] as NormalizedMessage[]
      case 'system':
        return [message] as NormalizedMessage[]
      case 'user': {
        // Mismo cast y misma razon que la rama `assistant`. `UserMessage`
        // declara `message` requerido —DIVERGENCIA declarada en
        // `messageShapes.ts`, misma clase que `AssistantMessage`— pero su
        // `content` sigue opcional, asi que se estrecha una sola vez a una
        // variable local en lugar de en los siete accesos de la rama.
        const um = message as UserMessage
        const userContent = (um.message.content ?? []) as string | ContentItem[]
        if (typeof userContent === 'string') {
          const uuid = isNewChain ? deriveUUID(um.uuid, 0) : um.uuid
          return [
            {
              ...um,
              uuid,
              message: {
                ...um.message,
                content: [{ type: 'text', text: userContent }],
              },
            } as NormalizedMessage,
          ]
        }
        isNewChain = isNewChain || userContent.length > 1
        // `imagePasteIds` no esta declarado en `Message`: llega por su firma de
        // indice, o sea `unknown`. Indexarlo sin estrechar es TS18046 —el mismo
        // acceso que la fuente hace legalmente bajo `strict: false`—.
        const imagePasteIds = um.imagePasteIds as number[] | undefined
        let imageIndex = 0
        return userContent.map((_, index) => {
          const isImage = _.type === 'image'
          // For image content blocks, extract just the ID for this image
